<script setup lang="ts">
import { ArrowUpRight, Check } from 'lucide-vue-next'
const api = useApi()
const { data: plans } = await useAsyncData('pricing-plans', () => api.request<any[]>('/plans').catch(() => []))
const miles = ref(1200)
const annual = computed(() => Math.max(2500 * 12, 14 * miles.value * 12))
const savings = computed(() => Math.max(0, Math.round(miles.value * 420 - annual.value)))
